def _headers(project: str, stream: str) -> dict[str, str]:
    headers = {}
    for entry in os.getenv('OTEL_EXPORTER_OTLP_TRACES_HEADERS', '').split(','):
        if not entry.strip(): continue
        key, value = entry.strip().split('=', 1)
        key, value = unquote(key).lower(), unquote(value)
        if key in headers or any(c in key+value for c in '\r\n'):
            raise ValueError('invalid_headers')
        headers[key] = value
    if 'agentstreamid' in headers:
        raise ValueError('unsupported_stream_alias')
    for key, value in (('projectid', project), ('logstreamid', stream)):
        if key in headers and headers[key] != value:
            raise ValueError('conflicting_resource_header')
        headers[key] = value
    return headers

